        citations: citations(['duboisBlackReconstruction', 'fanonWretchedEarth', 'gandhiHindSwaraj', 'cesaireDiscourseColonialism'], ['sepColonialism', 'panAfricanism', 'gomesWomenLiberation', 'bavoCoelhoMozambiqueEducation2022']),
