        citations: citations(['gandhiHindSwaraj', 'fanonWretchedEarth', 'lockeSecondTreatise', 'duboisBlackReconstruction'], ['sepColonialism', 'vdem', 'brandaoFrelimoViolence2023', 'vinesFrelimoDemocracy2023']),
