        citations: citations(['hobbesLeviathan', 'burkeReflections', 'nabucoAbolitionism'], ['foreignPolicy', 'oxfordMonarchyConstitution', 'openTextbook', 'moroccoConstitutionFrench2011', 'kuwaitConstitution1962Ilo', 'carnegieKuwaitParliament2025']),
