        citations: citations(['millOnLiberty', 'wollstonecraftRights', 'constantLibertyModerns'], ['sepLiberalism', 'sepLibertyPositiveNegative', 'colonialLiberalismExclusion', 'echrConvention', 'coeDemocraticCitizenship', 'ghanaConstitutionRights1992Official', 'frusChinaProvisionalConstitution1912', 'zarrowAfterEmpire2012', 'belgiumFirstConstitutionOfficialDutch']),
