        citations: citations(['lockeSecondTreatise', 'federalistPapers', 'millOnLiberty'], ['sepConstitutionalism', 'oxfordConstitutionalJustice', 'oxfordBritishConstitutionalism', 'unRuleLawHumanRights', 'echrConvention', 'coeDemocraticCitizenship', 'vdem', 'ghanaConstitution1992Official', 'quashigahGhanaConstitution1992', 'gyampoGrahamGhanaHybridity2014', 'belgiumConstitution1831French', 'belgiumFirstConstitutionOfficialDutch', 'belgianChamberConstitution1831Dutch', 'vanDenBergBelgianConstitution2018', 'deseureBelgianSovereignty2016', 'kuleuvenBelgianSovereigntyProject2020Dutch', 'frusChinaProvincialAssemblies1908', 'frusChinaProvisionalConstitution1912', 'changLateQingConstitutionalism1989', 'zhangConstitutionalReformsChina2024']),
