        citations: citations(['mahanInfluenceSeaPower', 'hobsonImperialism', 'mussoliniDoctrine'], ['oxfordPoliticalEconomyMilitarism', 'oxfordImperialism', 'oxfordColonialismEmpireSociology', 'koreaNationalCultureAnnexation1910', 'joKoreanJudicialImperialism2023', 'russianTurkestanZarafshan1874', 'pierceRussianCentralAsiaColonialRule1960', 'morrisonRussianRuleSamarkand2008', 'surkisPropertyPolygamyAlgeria2010French', 'seibertBelgianCongoForcedLabor2024', 'vaessenBelgianCongoLabor2001French']),
